    Bug 2000005 - Update documentation of menu-typed action buttons. r=tobyp


    Mention the menu context required to add menu entries to menu-typed action
    buttons in the manifest section of our action APIS.

    Differential Revision: https://phabricator.services.mozilla.com/D272487

diff --git a/mail/components/extensions/annotations/browserAction.json b/mail/components/extensions/annotations/browserAction.json
index d31801878b0..1045e40b184 100644
--- a/mail/components/extensions/annotations/browserAction.json
+++ b/mail/components/extensions/annotations/browserAction.json
@@ -1,4 +1,44 @@
 [
+  {
+    "namespace": "manifest",
+    "types": [
+      {
+        "$extend": "WebExtensionManifest",
+        "properties": {
+          "action": {
+            "properties": {
+              "type": {
+                "enums": {
+                  "menu": {
+                    "annotations": [
+                      {
+                        "text": "The $(ref:menus.ContextType.action_menu) context of the $(doc:menus) can be used to add menu entries to a menu-typed action button."
+                      }
+                    ]
+                  }
+                }
+              }
+            }
+          },
+          "browser_action": {
+            "properties": {
+              "type": {
+                "enums": {
+                  "menu": {
+                    "annotations": [
+                      {
+                        "text": "The $(ref:menus.ContextType.browser_action_menu) context of the $(doc:menus) can be used to add menu entries to a menu-typed browserAction button."
+                      }
+                    ]
+                  }
+                }
+              }
+            }
+          }
+        }
+      }
+    ]
+  },
   {
     "namespace": "action",
     "types": [
